16	// Generate a cryptographically secure random state value
17	function generateSecureState(): string {
18	  const array = new Uint8Array(32);
19	  crypto.getRandomValues(array);
20	  return Array.from(array, (byte) => byte.toString(16).padStart(2, "0")).join("");
21	}
