46	// Store OAuth state and PKCE parameters in sessionStorage
47	// Returns state and optional codeChallenge for use in authorization URL
48	// PKCE is optional - if crypto APIs are unavailable (HTTP context), falls back to standard OAuth
49	export async function storeOAuthState(
50	  identityProviderName: string,
51	  flowMode: OAuthFlowMode,
52	  returnUrl?: string,
53	  linkingUserName?: string,
54	): Promise<{ state: string; codeChallenge?: string }> {
55	  const state = generateSecureState();
56	
57	  // Try to generate PKCE parameters if crypto.subtle is available (HTTPS/localhost)
58	  // Falls back to standard OAuth flow if unavailable (HTTP context)
59	  let codeVerifier: string | undefined;
60	  let codeChallenge: string | undefined;
61	
62	  try {
63	    // Check if crypto.subtle is available (requires secure context: HTTPS or localhost)
64	    if (typeof crypto !== "undefined" && crypto.subtle) {
65	      codeVerifier = generateCodeVerifier();
66	      codeChallenge = await generateCodeChallenge(codeVerifier);
67	    } else {
68	      console.warn(
69	        "PKCE not available: crypto.subtle requires HTTPS. Falling back to standard OAuth flow without PKCE. " +
70	          "For enhanced security, please access Memos over HTTPS.",
71	      );
72	    }
73	  } catch (error) {
74	    // If PKCE generation fails for any reason, fall back to standard OAuth
75	    console.warn("Failed to generate PKCE parameters, falling back to standard OAuth:", error);
76	    codeVerifier = undefined;
77	    codeChallenge = undefined;
78	  }
79	
80	  const stateData: OAuthState = {
81	    state,
82	    identityProviderName,
83	    flowMode,
84	    timestamp: Date.now(),
85	    returnUrl,
86	    linkingUserName,
87	    codeVerifier, // Store for later retrieval in callback (undefined if PKCE not available)
88	  };
89	
90	  try {
91	    sessionStorage.setItem(STATE_STORAGE_KEY, JSON.stringify(stateData));
92	  } catch (error) {
93	    console.error("Failed to store OAuth state:", error);
94	    throw new Error("Failed to initialize OAuth flow");
95	  }
96	
97	  return { state, codeChallenge };
